// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        address newOwner = address(0x5678);

        vm.prank(attacker);
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));

        assertTrue(c.owner() != newOwner);
    }
}
